// Execute the actual page script with synthetic DOM and fetch responses.
const fs = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const script = fs.readFileSync('index.html', 'utf8').match(/<script>([\s\S]*?)<\/script>/)[1];
const elements = {key: {value: ''}, result: {textContent: ''}, mine: {}, all: {hidden: true}};
const pending = [];
vm.runInNewContext(script, {
  document: {getElementById: id => elements[id]},
  fetch: (path, options) => new Promise(resolve => pending.push({path, options, resolve}))
});
const reply = (request, ok, data) => request.resolve({ok, json: async () => data});
(async () => {
  elements.key.value = 'demo-organizer';
  elements.key.oninput();
  assert.equal(elements.all.hidden, false);
  const old = elements.all.onclick();
  assert.equal(pending[0].path, '/api/all');
  assert.equal(pending[0].options.headers['X-Demo-Key'], 'demo-organizer');
  elements.key.value = 'demo-alice';
  elements.key.oninput();
  assert.equal(elements.all.hidden, true);
  assert.equal(elements.result.textContent, '');
  reply(pending[0], true, [{member: 'bob'}]);
  await old;
  assert.equal(elements.result.textContent, '');
  const mine = elements.mine.onclick();
  assert.equal(pending[1].path, '/api/mine');
  assert.equal(pending[1].options.headers['X-Demo-Key'], 'demo-alice');
  reply(pending[1], true, [{member: 'alice'}]);
  await mine;
  assert.deepEqual(JSON.parse(elements.result.textContent), [{member: 'alice'}]);
  elements.key.value = 'invalid';
  elements.key.oninput();
  assert.equal(elements.result.textContent, '');
  const denied = elements.mine.onclick();
  reply(pending[2], false, {error: '请输入有效的演示凭据'});
  await denied;
  assert.equal(elements.result.textContent, '请输入有效的演示凭据');
  const first = elements.mine.onclick();
  const second = elements.mine.onclick();
  reply(pending[4], true, []);
  await second;
  reply(pending[3], true, [{member: 'old'}]);
  await first;
  assert.equal(elements.result.textContent, '[]');
  console.log('PASS: role button, credential forwarding, result clearing, stale responses, error display');
})().catch(error => {console.error(error); process.exitCode = 1;});

// Exercise the actual page script without a browser or third-party packages.
const {readFileSync} = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const elements = {key: {value: ''}, result: {textContent: ''}, mine: {}, all: {hidden: true}};
const pending = [];
const script = readFileSync('index.html', 'utf8').match(/<script>([\s\S]*?)<\/script>/)[1];
vm.runInNewContext(script, {
  document: {getElementById: id => elements[id]},
  fetch: (path, options) => new Promise(resolve => pending.push({path, options, resolve})),
});
const reply = async (request, ok, value) => {
  request.resolve({ok, json: async () => value});
  await new Promise(resolve => setImmediate(resolve));
};
(async () => {
  elements.key.value = 'demo-organizer'; elements.key.oninput();
  assert.equal(elements.all.hidden, false);
  elements.all.onclick();
  assert.equal(pending[0].path, '/api/all');
  assert.equal(pending[0].options.headers['X-Demo-Key'], 'demo-organizer');
  elements.key.value = 'demo-alice'; elements.key.oninput();
  assert.equal(elements.all.hidden, true);
  assert.equal(elements.result.textContent, '');
  await reply(pending.shift(), true, [{id: 'r-b'}]);
  assert.equal(elements.result.textContent, ''); // Old organizer response cannot reappear.
  elements.mine.onclick();
  assert.equal(pending[0].path, '/api/mine');
  await reply(pending.shift(), true, [{id: 'r-a'}]);
  assert.equal(JSON.parse(elements.result.textContent)[0].id, 'r-a');
  elements.key.value = 'invalid'; elements.key.oninput(); elements.mine.onclick();
  await reply(pending.shift(), false, {error: '请输入有效的演示凭据'});
  assert.equal(elements.result.textContent, '请输入有效的演示凭据');
  console.log('PASS: original buttons, credential switching, stale response isolation, error display');
})().catch(error => {console.error(error); process.exitCode = 1;});

