"""Local HTTP regression checks using only the existing synthetic records."""
import http.client
import json
import threading
import unittest

from server import Handler, ROWS, ThreadingHTTPServer


class AccessTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.server = ThreadingHTTPServer(("127.0.0.1", 0), Handler)
        cls.thread = threading.Thread(target=cls.server.serve_forever)
        cls.thread.start()

    @classmethod
    def tearDownClass(cls):
        cls.server.shutdown()
        cls.server.server_close()
        cls.thread.join()

    def request(self, path, key=None):
        connection = http.client.HTTPConnection("127.0.0.1", self.server.server_port)
        headers = {} if key is None else {"X-Demo-Key": key}
        connection.request("GET", path, headers=headers)
        response = connection.getresponse()
        body = response.read()
        status = response.status
        if path.startswith("/api/"):
            self.assertEqual(response.getheader("Cache-Control"), "no-store")
            body = json.loads(body)
        connection.close()
        return status, body

    def test_existing_page(self):
        status, body = self.request("/")
        self.assertEqual(status, 200)
        self.assertIn(b"/api/mine", body)
        self.assertIn(b"/api/all", body)

    def test_members_see_only_own_record(self):
        for key, row in zip(("demo-alice", "demo-bob"), ROWS):
            for suffix in ("", "?member=" + row["member"]):
                self.assertEqual(self.request("/api/mine" + suffix, key), (200, [row]))

    def test_missing_and_invalid_credentials(self):
        for key in (None, "", "invalid"):
            for path in ("/api/mine", "/api/mine?member=alice", "/api/all"):
                status, body = self.request(path, key)
                self.assertEqual(status, 401)
                self.assertEqual(set(body), {"error"})

    def test_member_cannot_read_full_list(self):
        for key in ("demo-alice", "demo-bob"):
            status, body = self.request("/api/all", key)
            self.assertEqual(status, 403)
            self.assertEqual(set(body), {"error"})

    def test_identity_override_is_denied(self):
        for key, other in (("demo-alice", "bob"), ("demo-bob", "alice"),
                           ("demo-organizer", "alice")):
            status, body = self.request("/api/mine?member=" + other, key)
            self.assertEqual(status, 403)
            self.assertEqual(set(body), {"error"})
        for query in ("member=", "member=alice&member=bob", "member=bob&member=alice",
                      "member=alice&member=alice", "member=%62ob"):
            self.assertEqual(self.request("/api/mine?" + query, "demo-alice")[0], 403)

    def test_organizer_existing_flow(self):
        self.assertEqual(self.request("/api/all", "demo-organizer"), (200, ROWS))
        self.assertEqual(self.request("/api/mine", "demo-organizer"), (200, []))


if __name__ == "__main__":
    unittest.main()

